    internal static void Run()
    {
        if (Environment.GetEnvironmentVariable("AK_GATE_PLANT_NO_INIT") == "1") { Code = -999; return; }
        var o = new ak_init_opts { abi_version = AkRpc.AK_ABI_VERSION, flags = Flags };
        var e = new ak_err();
        int rc = AkRpc.ak_init(&o, &e);
        Code = rc;
        if (rc != AkRpc.AK_OK && rc != AkRpc.AK_ALREADY_INITIALIZED)
            throw new InvalidOperationException($"ak_init failed: {rc} (code {e.code}, detail {e.detail})");
    }
}

